/**
 * DSA roadmap: every problem in NeetCode 250 + CSES placed in a learning order.
 *
 * Generated from docs/DSA_Roadmap_Recategorized.xlsx (sheet "All Problems"); keep the two in
 * sync. Topics run in teaching order. Inside a topic, the Core tier (difficulty score < 6) comes
 * before the Challenge tier; inside a tier, problems that use the same technique share a group,
 * groups follow a teaching order, and problems in a group run from easiest to hardest.
 *
 * Difficulty score (1-10): NeetCode from LeetCode difficulty + acceptance rate; CSES from the
 * number of solvers on cses.fi (log scale). Both read on 2026-11-15.
 */

export type RoadmapTier = 'core' | 'challenge'
export type RoadmapLevel = 'beginner' | 'easy' | 'medium' | 'hard' | 'very-hard'

export type RoadmapTopic = {
  id: string
  /** 1-based position in the roadmap. */
  order: number
  title: string
  focus: string
  /** Group names in teaching order. */
  groups: string[]
}

export type RoadmapEntry = {
  /** 1-based position of the problem across the whole roadmap. */
  order: number
  topicId: string
  tier: RoadmapTier
  group: string
  score: number
  level: RoadmapLevel
  /** Where the score came from, e.g. "LeetCode medium, 62% acceptance". */
  basis: string
  /** Placement rests on the title/section rather than a read of the full statement. */
  needsReview?: true
}

export const ROADMAP_LEVELS: { id: RoadmapLevel; label: string }[] = [
  { id: 'beginner', label: 'Beginner' },
  { id: 'easy', label: 'Easy' },
  { id: 'medium', label: 'Medium' },
  { id: 'hard', label: 'Hard' },
  { id: 'very-hard', label: 'Very hard' },
]

